//! Interop tests against real sing-box TUIC v5 servers.
//!
//! These tests are ignored by default; the `REALITY interop (Linux)` CI job
//! starts the servers and targets and runs them with `--ignored`. Inputs:
//!
//! * `NC_TUIC_SERVERS`: `name=host:port,...`
//! * `NC_TUIC_UUID`, `NC_TUIC_PASSWORD`
//! * `NC_TUIC_SERVER_NAME`: name in the servers' self-signed certificate
//! * `NC_HTTP_TARGET`: plain HTTP/1.0 server serving `/payload.bin`
//!   generated by [`expected_payload`]

use std::io;
use std::net::SocketAddr;
use std::time::Duration;

use engine_outbound::{TargetAddr, TcpOutbound};
use outbound_tuic::{parse_uuid, TuicOutbound};
use tokio::io::{AsyncReadExt, AsyncWriteExt};
use transport_quic::Congestion;
use transport_tls::TlsSettings;

const PAYLOAD_LEN: usize = 1_000_000;
const TIMEOUT: Duration = Duration::from_secs(60);

fn expected_payload() -> Vec<u8> {
    (0..PAYLOAD_LEN)
        .map(|i| ((i * 7 + 3) % 251) as u8)
        .collect()
}

fn env(name: &str) -> String {
    std::env::var(name).unwrap_or_else(|_| panic!("{name} must be set for interop tests"))
}

fn servers() -> Vec<(String, String, u16)> {
    env("NC_TUIC_SERVERS")
        .split(',')
        .map(|entry| {
            let (name, rest) = entry.split_once('=').expect("name=host:port");
            let (host, port) = rest.rsplit_once(':').expect("host:port");
            (name.to_owned(), host.to_owned(), port.parse().unwrap())
        })
        .collect()
}

fn outbound(host: &str, port: u16, password: &str, congestion: Congestion) -> TuicOutbound {
    let tls = TlsSettings {
        server_name: env("NC_TUIC_SERVER_NAME"),
        alpn: Vec::new(),
        insecure: true,
    };
    let uuid = parse_uuid(&env("NC_TUIC_UUID")).unwrap();
    TuicOutbound::new(host, port, uuid, password, &tls, congestion).unwrap()
}

async fn fetch_payload(outbound: &TuicOutbound) -> io::Result<Vec<u8>> {
    let target = TargetAddr::from(env("NC_HTTP_TARGET").parse::<SocketAddr>().unwrap());
    let mut stream = outbound.connect(&target).await?;
    stream
        .write_all(b"GET /payload.bin HTTP/1.0\r\nHost: interop.test\r\n\r\n")
        .await?;
    stream.flush().await?;
    let mut response = Vec::new();
    stream.read_to_end(&mut response).await?;
    let split = response
        .windows(4)
        .position(|window| window == b"\r\n\r\n")
        .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidData, "no HTTP header terminator"))?;
    let status = String::from_utf8_lossy(&response[..split]).to_string();
    if !(status.starts_with("HTTP/1.0 200") || status.starts_with("HTTP/1.1 200")) {
        return Err(io::Error::other(format!("unexpected status: {status}")));
    }
    Ok(response[split + 4..].to_vec())
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
#[ignore = "needs the REALITY interop CI environment"]
async fn downloads_through_every_server() {
    let expected = expected_payload();
    let password = env("NC_TUIC_PASSWORD");
    let mut failures = Vec::new();
    for (name, host, port) in servers() {
        for congestion in [Congestion::Cubic, Congestion::Bbr] {
            let outbound = outbound(&host, port, &password, congestion);
            // The second download reuses the authenticated QUIC connection.
            for round in 1..=2 {
                let label = format!("{name} {congestion:?} round {round}");
                match tokio::time::timeout(TIMEOUT, fetch_payload(&outbound)).await {
                    Ok(Ok(body)) if body == expected => {
                        eprintln!("{label}: ok, {} bytes", body.len())
                    }
                    Ok(Ok(body)) => failures.push(format!("{label}: {} bytes differ", body.len())),
                    Ok(Err(error)) => failures.push(format!("{label}: {error}")),
                    Err(_) => failures.push(format!("{label}: timed out")),
                }
            }
        }

        // TUIC servers do not answer Authenticate; a wrong password must not
        // yield the payload.
        let wrong = self::outbound(&host, port, "not-the-password", Congestion::Cubic);
        match tokio::time::timeout(TIMEOUT, fetch_payload(&wrong)).await {
            Ok(Ok(_)) => failures.push(format!("{name} wrong password: downloaded")),
            Ok(Err(error)) => eprintln!("{name} wrong password: rejected ({error})"),
            Err(_) => eprintln!("{name} wrong password: no data"),
        }
    }
    assert!(failures.is_empty(), "failures:\n{}", failures.join("\n"));
}
